      "staff.guide.title": "How to use the Site Editor",
      "staff.guide.hide": "Hide guide",
      "staff.guide.show": "Show guide",
      "staff.guide.intro": "Anything you change here updates the live public website right away — across every page and in the language you pick. Nothing is permanent: every field has its own Reset, and you can undo all of your edits at the bottom of this page.",
      "staff.guide.s1t": "Pick the language",
      "staff.guide.s1b": "Use “Editing language” to choose which language you are editing. Each language is stored separately — editing English does not change Thai.",
      "staff.guide.s2t": "Find the text",
      "staff.guide.s2b": "Scroll the grouped sections (Hero, Rooms, Dining…) or type in the search box to jump straight to any words shown on the site.",
      "staff.guide.s3t": "Edit and it saves itself",
      "staff.guide.s3b": "Click a field, change the words, then click away. It saves automatically and a green “Saved” appears. Press Reset on a field to restore the original.",
      "staff.guide.s4t": "Manage photos & videos",
      "staff.guide.s4b": "On the Photos & videos tab, open any section to add, replace, reorder, or remove photos and videos. Upload a photo from your computer or paste an image or video link. The order you set here is the order guests see, and the first photo is that section's cover — reload the page on the website to see it.",
      "staff.guide.s5t": "Change colours",
      "staff.guide.s5b": "In “Colours & theme”, pick new brand colours. The whole site restyles instantly.",
      "staff.guide.s6t": "Show, hide & announce",
      "staff.guide.s6b": "Hide a whole section with one tick, or post an announcement banner that appears across the top of the site.",
      "staff.guide.s7t": "Rates are live, not cosmetic",
      "staff.guide.s7b": "Unlike every other tab, a change on the Rates tab affects real guest charges the moment you click Save — there is no draft step and no \"Undo all my edits\" safety net for rates.",
      "staff.guide.s8t": "Live Chat answers",
      "staff.guide.s8b": "On the Live Chat tab, reword what the chat assistant tells guests, change the times or details inside any answer, choose which words trigger it, or add a new answer of your own. Type once in your language and it is translated into the other four. Click Save Live Chat to publish — it reaches every guest device.",
      "staff.guide.tipTitle": "Good to know",
      "staff.guide.tip1": "Open the website in a second tab and keep it beside this one — your edits appear there live as you type.",
      "staff.guide.tip2": "A field left exactly as the original stores nothing — only your real changes are kept.",
      "staff.guide.tip3": "Edits are auto-translated to all 5 languages — review each language tab if you want to fine-tune the wording.",
      "staff.guide.tip4": "The Rates tab is the one exception to \"nothing is permanent\" — double-check a number before saving, since it takes effect on the very next booking.",
      "staff.guide.openSite": "Open the website ↗",
