      "staff.guide.intro": "ทุกสิ่งที่คุณเปลี่ยนที่นี่จะอัปเดตเว็บไซต์สาธารณะทันที — ทุกหน้าและในภาษาที่คุณเลือก ไม่มีอะไรถาวร ทุกช่องมีปุ่มรีเซ็ตของตัวเอง และคุณสามารถยกเลิกการแก้ไขทั้งหมดได้ที่ด้านล่างของหน้านี้",
