      "staff.guide.s1b": "ใช้ “ภาษาที่กำลังแก้ไข” เพื่อเลือกภาษาที่คุณกำลังแก้ไข แต่ละภาษาเก็บแยกกัน — การแก้ไขภาษาอังกฤษไม่เปลี่ยนภาษาไทย",
      "staff.guide.s2t": "ค้นหาข้อความ",
      "staff.guide.s2b": "เลื่อนดูกลุ่มต่าง ๆ (Hero, ห้องพัก, ร้านอาหาร…) หรือพิมพ์ในช่องค้นหาเพื่อไปยังข้อความใด ๆ บนเว็บไซต์ได้ทันที",
      "staff.guide.s3t": "แก้ไขแล้วบันทึกอัตโนมัติ",
      "staff.guide.s3b": "คลิกที่ช่อง แก้ไขข้อความ แล้วคลิกที่อื่น ระบบจะบันทึกอัตโนมัติและขึ้นคำว่า “บันทึกแล้ว” สีเขียว กดรีเซ็ตที่ช่องเพื่อคืนค่าเดิม",
      "staff.guide.s4t": "จัดการรูปภาพและวิดีโอ",
      "staff.guide.s4b": "ในแท็บ “รูปภาพและวิดีโอ” เปิดส่วนใดก็ได้เพื่อเพิ่ม เปลี่ยน จัดลำดับ หรือลบรูปภาพและวิดีโอ อัปโหลดรูปจากคอมพิวเตอร์หรือวางลิงก์รูปภาพหรือวิดีโอ ลำดับที่ตั้งไว้ที่นี่คือลำดับที่ผู้เข้าพักเห็น และรูปแรกคือภาพหน้าปกของส่วนนั้น — โหลดหน้าเว็บไซต์ใหม่เพื่อดูผลลัพธ์",
      "staff.guide.s5t": "เปลี่ยนสี",
      "staff.guide.s5b": "ในส่วน “สีและธีม” เลือกสีแบรนด์ใหม่ ทั้งเว็บไซต์จะเปลี่ยนสไตล์ทันที",
      "staff.guide.s6t": "แสดง ซ่อน และประกาศ",
      "staff.guide.s6b": "ซ่อนทั้งส่วนได้ด้วยการติ๊กครั้งเดียว หรือโพสต์แบนเนอร์ประกาศที่แสดงด้านบนสุดของเว็บไซต์",
      "staff.guide.s7t": "ราคาเป็นข้อมูลจริง ไม่ใช่แค่การตกแต่ง",
      "staff.guide.s7b": "ต่างจากแท็บอื่น ๆ การเปลี่ยนแปลงในแท็บราคาจะมีผลกับยอดเรียกเก็บเงินจริงของผู้เข้าพักทันทีที่กดบันทึก — ไม่มีขั้นตอนแบบร่างและไม่มีปุ่ม \"ยกเลิกการแก้ไขทั้งหมด\" รองรับสำหรับราคา",
      "staff.guide.s8t": "คำตอบแชทสด",
      "staff.guide.s8b": "ในแท็บแชทสด คุณสามารถแก้ถ้อยคำที่ผู้ช่วยแชทบอกผู้เข้าพัก เปลี่ยนเวลาหรือรายละเอียดในคำตอบใด ๆ เลือกคำที่ใช้กระตุ้น หรือเพิ่มคำตอบใหม่ของคุณเอง พิมพ์ครั้งเดียวในภาษาของคุณ แล้วระบบจะแปลเป็นอีกสี่ภาษา กดบันทึกแชทสดเพื่อเผยแพร่ — จะไปถึงอุปกรณ์ของผู้เข้าพักทุกเครื่อง",
      "staff.guide.tipTitle": "ข้อควรรู้",
      "staff.guide.tip1": "เปิดเว็บไซต์ในอีกแท็บหนึ่งและวางไว้ข้าง ๆ — การแก้ไขของคุณจะปรากฏที่นั่นทันทีขณะพิมพ์",
      "staff.guide.tip2": "ช่องที่ปล่อยไว้เหมือนต้นฉบับจะไม่ถูกบันทึก — เก็บเฉพาะการเปลี่ยนแปลงจริงเท่านั้น",
      "staff.guide.tip3": "การแก้ไขจะถูกแปลอัตโนมัติเป็นทุกภาษา — ตรวจสอบแต่ละแท็บภาษาหากต้องการปรับถ้อยคำ",
      "staff.guide.tip4": "แท็บราคาเป็นข้อยกเว้นเดียวของ \"ไม่มีอะไรถาวร\" — ตรวจสอบตัวเลขให้ดีก่อนบันทึก เพราะจะมีผลกับการจองครั้งถัดไปทันที",
      "staff.guide.openSite": "เปิดเว็บไซต์ ↗",
