      "staff.site.grpBrand": "ブランド・ナビゲーション",
      "staff.site.grpHero": "トップのヒーロー",
      "staff.site.grpServices": "ゲストサービス・ポータル",
      "staff.site.grpFooter": "フッター",
      "staff.site.grpChat": "チャットボットの回答",
      "staff.guide.title": "サイト編集の使い方",
      "staff.guide.hide": "ガイドを隠す",
      "staff.guide.show": "ガイドを表示",
      "staff.guide.intro": "ここでの変更は、すべてのページと選んだ言語で、公開サイトに即時反映されます。永久的なものは一つもありません。各項目に個別のリセットがあり、このページの一番下ですべての編集を取り消せます。",
      "staff.guide.s1t": "言語を選ぶ",
      "staff.guide.s1b": "「編集中の言語」で編集する言語を選びます。各言語は別々に保存され、英語を編集してもタイ語は変わりません。",
      "staff.guide.s2t": "文章を探す",
      "staff.guide.s2b": "グループ（ヒーロー、客室、ダイニング…）をスクロールするか、検索ボックスに入力してサイト上の任意の文章にすぐ移動できます。",
      "staff.guide.s3t": "編集すれば自動保存",
      "staff.guide.s3b": "項目をクリックして文章を変え、外をクリックします。自動的に保存され、緑色の「保存しました」が表示されます。項目のリセットで元に戻せます。",
      "staff.guide.s4t": "写真・動画を管理する",
      "staff.guide.s4b": "「写真・動画」タブでセクションを開き、写真や動画の追加・差し替え・並べ替え・削除ができます。パソコンから写真をアップロードするか、画像または動画のリンクを貼り付けてください。ここで決めた並び順がそのままお客様に表示され、先頭の写真がそのセクションの表紙になります — ウェブサイトのページを再読み込みすると確認できます。",
      "staff.guide.s5t": "色を変える",
      "staff.guide.s5b": "「色・テーマ」で新しいブランドカラーを選びます。サイト全体が即座にスタイル変更されます。",
      "staff.guide.s6t": "表示・非表示・お知らせ",
      "staff.guide.s6b": "チェック一つでセクション全体を隠したり、サイト上部に表示されるお知らせバナーを投稿できます。",
      "staff.guide.s7t": "料金タブは実際の料金に反映されます",
      "staff.guide.s7b": "他のタブと異なり、料金タブでの変更は保存した瞬間から実際の宿泊料金に反映されます — 下書きの手順はなく、料金には「自分の編集をすべて取り消す」も適用されません。",
      "staff.guide.s8t": "ライブチャットの回答",
      "staff.guide.s8b": "ライブチャットタブでは、チャットアシスタントが宿泊客に伝える文言を書き換え、回答内の時間や詳細を変更し、呼び出すキーワードを選び、独自の回答を追加できます。ご自分の言語で一度入力すれば、残り4言語へ翻訳されます。「ライブチャットを保存」を押すと公開され、すべての宿泊客の端末に届きます。",
      "staff.guide.tipTitle": "知っておくと便利",
      "staff.guide.tip1": "ウェブサイトを別のタブで開いて横に並べておくと、入力するそばから編集が反映されます。",
      "staff.guide.tip2": "元のままの項目は何も保存されません。実際の変更だけが保持されます。",
      "staff.guide.tip3": "編集内容はすべての言語に自動翻訳されます — 表現を微調整したい場合は各言語タブをご確認ください。",
      "staff.guide.tip4": "料金タブだけは「永久的なものは一つもない」の例外です — 次のご予約から即座に反映されるため、保存前に数字をよくご確認ください。",
      "staff.guide.openSite": "ウェブサイトを開く ↗",
