      "staff.guide.title": "如何使用网站编辑器",
      "staff.guide.hide": "隐藏指南",
      "staff.guide.show": "显示指南",
      "staff.guide.intro": "您在此处的任何更改都会立即更新到公开网站 — 涵盖每个页面，并且只影响您选择的语言。没有任何更改是永久的：每个字段都有各自的重置，您也可以在本页底部撤销全部修改。",
      "staff.guide.s1t": "选择语言",
      "staff.guide.s1b": "用“正在编辑的语言”选择您要编辑的语言。每种语言分开保存 — 编辑英文不会改变泰文。",
      "staff.guide.s2t": "找到文字",
      "staff.guide.s2b": "滚动浏览分组（主图、客房、餐饮…），或在搜索框中输入，直接跳到网站上显示的任何文字。",
      "staff.guide.s3t": "编辑即自动保存",
      "staff.guide.s3b": "点击字段，修改文字，然后点击别处。它会自动保存并显示绿色的“已保存”。点击字段上的重置可恢复原文。",
      "staff.guide.s4t": "管理照片与视频",
      "staff.guide.s4b": "在”照片与视频”选项卡中，打开任意板块即可添加、替换、排序或删除照片和视频。从电脑上传照片，或粘贴图片或视频链接。这里设定的顺序就是访客看到的顺序，第一张照片即该板块的封面 — 重新载入网站页面即可看到效果。",
      "staff.guide.s5t": "更改颜色",
      "staff.guide.s5b": "在“颜色与主题”中选择新的品牌颜色，整个网站会立即改变风格。",
      "staff.guide.s6t": "显示、隐藏与公告",
      "staff.guide.s6b": "勾选一下即可隐藏整个板块，或发布显示在网站顶部的公告横幅。",
      "staff.guide.s7t": "房价是实时数据，不是装饰性内容",
      "staff.guide.s7b": "与其他选项卡不同，房价选项卡中的更改会在您点击保存的瞬间影响真实的客人扣款金额 — 没有草稿步骤，「撤销我的全部修改」也不适用于房价。",
      "staff.guide.s8t": "在线聊天回答",
      "staff.guide.s8b": "在“在线聊天”选项卡中，你可以改写聊天助手对客人说的话，修改任意回答中的时间或细节，选择触发它的词语，或添加你自己的新回答。用你的语言输入一次，系统会翻译成另外四种语言。点击“保存在线聊天”即可发布 — 它会送达每位客人的设备。",
      "staff.guide.tipTitle": "实用提示",
      "staff.guide.tip1": "在另一个标签页打开网站并放在旁边 — 您输入时编辑会实时显示在那里。",
      "staff.guide.tip2": "与原文完全相同的字段不会保存任何内容 — 只保留您真正的更改。",
      "staff.guide.tip3": "编辑内容会自动翻译为所有语言 — 如需微调措辞，请查看每个语言选项卡。",
