      "chat.a.checkin": "入住時間為14:00起，退房時間為12:00前。延遲退房至15:00免費（視客房狀況而定），至18:00收取฿500，之後按整晚房費收取。如需辦理，請開啟賓客服務 → 櫃檯，輕點「申請延遲退房」。",
