      "staff.guide.title": "如何使用網站編輯器",
      "staff.guide.hide": "隱藏指南",
      "staff.guide.show": "顯示指南",
      "staff.guide.intro": "您在此處的任何更改都會立即更新到公開網站 — 涵蓋每個頁面，並且只影響您選擇的語言。沒有任何更改是永久的：每個欄位都有各自的重設，您也可以在本頁底部復原全部修改。",
      "staff.guide.s1t": "選擇語言",
      "staff.guide.s1b": "用「正在編輯的語言」選擇您要編輯的語言。每種語言分開儲存 — 編輯英文不會改變泰文。",
      "staff.guide.s2t": "找到文字",
      "staff.guide.s2b": "捲動瀏覽分組（主圖、客房、餐飲…），或在搜尋框中輸入，直接跳到網站上顯示的任何文字。",
      "staff.guide.s3t": "編輯即自動儲存",
      "staff.guide.s3b": "點擊欄位，修改文字，然後點擊別處。它會自動儲存並顯示綠色的「已儲存」。點擊欄位上的重設可恢復原文。",
      "staff.guide.s4t": "管理照片與影片",
      "staff.guide.s4b": "在「照片與影片」索引標籤中，開啟任一版塊即可新增、替換、排序或刪除照片和影片。從電腦上傳照片，或貼上圖片或影片連結。這裡設定的順序就是訪客看到的順序，第一張照片即該版塊的封面 — 重新載入網站頁面即可看到效果。",
      "staff.guide.s5t": "更改顏色",
      "staff.guide.s5b": "在「顏色與主題」中選擇新的品牌顏色，整個網站會立即改變風格。",
      "staff.guide.s6t": "顯示、隱藏與公告",
      "staff.guide.s6b": "勾選一下即可隱藏整個區塊，或發佈顯示在網站頂部的公告橫幅。",
      "staff.guide.s7t": "房價是即時資料，並非裝飾性內容",
      "staff.guide.s7b": "與其他分頁不同，房價分頁中的變更會在您點擊儲存的當下立即影響真實的房客扣款金額 — 沒有草稿步驟，「復原我的全部修改」也不適用於房價。",
      "staff.guide.s8t": "線上聊天回答",
      "staff.guide.s8b": "在「線上聊天」分頁中，你可以改寫聊天助手對房客所說的話，修改任何回答中的時間或細節，選擇觸發它的詞語，或新增你自己的新回答。用你的語言輸入一次，系統會翻譯成另外四種語言。點擊「儲存線上聊天」即可發佈 — 它會送達每位房客的裝置。",
      "staff.guide.tipTitle": "實用提示",
      "staff.guide.tip1": "在另一個分頁開啟網站並放在旁邊 — 您輸入時編輯會即時顯示在那裡。",
      "staff.guide.tip2": "與原文完全相同的欄位不會儲存任何內容 — 只保留您真正的更改。",
      "staff.guide.tip3": "編輯內容會自動翻譯為所有語言 — 如需微調措辭，請查看每個語言分頁。",
      "staff.guide.tip4": "房價分頁是「沒有什麼是永久的」這句話唯一的例外 — 儲存前請仔細核對數字，因為它會立即影響下一筆預訂。",
      "staff.guide.openSite": "開啟網站 ↗",
